/* C evaluation fixture for the bounded polyhedral optimizer. */
long kernel(long seed){double a[1024],b[8192],c[2048];for(long x=0;x<1024;x++)a[x]=(x+seed)&15;for(long x=0;x<8192;x++)b[x]=(x*3)&7;for(long x=0;x<2048;x++)c[x]=1;for(long i=0;i<16;i++)for(long j=0;j<128;j++)for(long t=0;t<64;t++)c[i*128+j]+=a[i*64+t]*b[j*64+t];long sum=0;for(long i=0;i<16;i++)for(long j=0;j<128;j++)sum+=(long)c[i*128+j]*(i+j+1);return sum;}
